arguments.old_string:
export function parseDate(input) {
  return new Date(input);
}

arguments.new_string:
export function parseDate(input) {
  if (input === '') {
    return null;
  }
  return new Date(input);
}

arguments.old_string:
test('ISO 日期解析保留原有行为', () => {
  assert.equal(parseDate('2026-09-23T00:00:00Z').toISOString(), '2026-09-23T00:00:00.000Z');
});

arguments.new_string:
test('ISO 日期解析保留原有行为', () => {
  assert.equal(parseDate('2026-09-23T00:00:00Z').toISOString(), '2026-09-23T00:00:00.000Z');
});

test('空字符串返回 null', () => {
  assert.equal(parseDate(''), null);
});
